import 'dart:convert';
import 'dart:typed_data';

/// Embedded STI College logo bytes used by QuestionPaperPdfService for both
/// on-screen PDF preview/print and Microsoft Word (.docx) generation.
class StiLogoData {
  StiLogoData._();

  static const String _base64Logo = '';

  static Uint8List? _cachedBytes;

  static Uint8List get bytes => _cachedBytes ??= base64Decode(_base64Logo);
}
